const raw = $input.first().json.output || '';

// Strip markdown code fences if the model wraps the JSON
const cleaned = raw.replace(/```json\n?|\n?```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (e) {
  return [{
    json: {
      message: "I'm sorry, I had a brief issue. Could you please repeat that?",
      lead_data: { name: '', phone: '', email: '', interest: '', viewing_date: '', lead_score: 0, is_complete: false },
      is_complete: false,
      has_viewing: false,
      viewing_date_iso: '',
      viewing_date_iso_end: ''
    }
  }];
}

const ld = parsed.lead_data || {};

const phone = String(ld.phone || '').trim();

// Convert "YYYY-MM-DD HH:MM" → ISO 8601 "YYYY-MM-DDTHH:MM:00" for Google Calendar
const rawDate = typeof ld.viewing_date === 'string' ? ld.viewing_date.trim() : '';
let viewingIso = '';
let viewingIsoEnd = '';
if (rawDate) {
  viewingIso = rawDate.replace(' ', 'T');
  if (!viewingIso.includes('T')) viewingIso = viewingIso + 'T09:00';
  if (viewingIso.length === 16) viewingIso += ':00';
  // Wall-clock +1h using local getters so the server timezone never shifts the end time
  const d = new Date(viewingIso);
  if (!isNaN(d.getTime())) {
    d.setHours(d.getHours() + 1);
    const pad = n => String(n).padStart(2, '0');
    viewingIsoEnd = d.getFullYear() + '-' + pad(d.getMonth() + 1) + '-' + pad(d.getDate()) + 'T' + pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':00';
  } else {
    viewingIsoEnd = viewingIso;
  }
}

return [{
  json: {
    message: parsed.message || '',
    lead_data: {
      name:         ld.name         || '',
      phone:        phone,
      email:        ld.email        || '',
      interest:     ld.interest     || '',
      viewing_date: rawDate,
      lead_score:   Number(ld.lead_score) || 0
    },
    is_complete:          ld.is_complete === true,
    has_viewing:          rawDate !== '',
    viewing_date_iso:     viewingIso,
    viewing_date_iso_end: viewingIsoEnd
  }
}];

